<x-filament-panels::page>
    <style>
        .orion-po-form{direction:rtl;--pf-panel:#0d1728;--pf-panel2:#111c30;--pf-border:#263853;--pf-soft:#1b2a41;--pf-text:#f8fafc;--pf-muted:#8091aa;--pf-purple:#8b5cf6;--pf-green:#34d399;--pf-amber:#fbbf24;--pf-blue:#60a5fa}.orion-po-form *{box-sizing:border-box}
        .pf-steps{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:10px;margin-bottom:14px}.pf-step{position:relative;overflow:hidden;min-height:82px;padding:13px 15px;border:1px solid var(--pf-border);border-radius:14px;background:linear-gradient(145deg,var(--pf-panel2),#0b1525)}.pf-step::after{content:"";position:absolute;right:0;left:0;bottom:0;height:2px;background:linear-gradient(90deg,transparent,var(--accent),transparent);opacity:.75}.pf-step-top{display:flex;justify-content:space-between;align-items:center;gap:8px}.pf-step-no{width:25px;height:25px;display:flex;align-items:center;justify-content:center;border-radius:8px;border:1px solid color-mix(in srgb,var(--accent) 35%,#31435f);background:color-mix(in srgb,var(--accent) 8%,#0f192b);color:var(--accent);font-size:9px;font-weight:950}.pf-step-title{color:#dce5f1;font-size:10px;font-weight:900}.pf-step-note{margin-top:8px;color:#687a93;font-size:8px;line-height:1.6}
        .pf-layout{display:grid;grid-template-columns:minmax(0,1fr) 295px;gap:14px;align-items:start}.pf-shell,.pf-card{border:1px solid var(--pf-border);border-radius:16px;background:linear-gradient(145deg,#0d1728,#091321);box-shadow:0 16px 38px rgba(0,0,0,.14)}.pf-shell{overflow:hidden}.pf-head{display:flex;align-items:center;justify-content:space-between;gap:12px;padding:14px 17px;border-bottom:1px solid var(--pf-soft);background:#0f192b}.pf-title{font-size:15px;font-weight:950;color:var(--pf-text)}.pf-sub{margin-top:3px;font-size:9px;color:#6b7d96}.pf-status{display:inline-flex;align-items:center;gap:6px;padding:5px 9px;border:1px solid rgba(96,165,250,.18);border-radius:999px;background:rgba(96,165,250,.055);color:#93c5fd;font-size:9px;font-weight:900}.pf-status::before{content:"";width:5px;height:5px;border-radius:50%;background:var(--pf-blue)}.pf-form{padding:16px}.pf-actions{margin-top:16px;padding-top:14px;border-top:1px solid var(--pf-soft)}
        .pf-side{display:grid;gap:12px;position:sticky;top:16px}.pf-card{padding:15px}.pf-kicker{font-size:8px;letter-spacing:.08em;color:#7d6ab0;font-weight:950;direction:ltr;text-align:right}.pf-card-title{margin-top:5px;color:#f5f8fc;font-size:14px;font-weight:950}.pf-text{margin-top:8px;color:#71829b;font-size:9px;line-height:1.8}.pf-checks{margin-top:12px;border-top:1px solid #1b2a41}.pf-check{display:flex;gap:8px;padding:10px 0;border-bottom:1px solid #17243a}.pf-check:last-child{border-bottom:0}.pf-dot{width:7px;height:7px;margin-top:5px;border-radius:50%;background:var(--dot);flex:0 0 auto}.pf-check strong{display:block;color:#dce5f1;font-size:9px}.pf-check span{display:block;margin-top:2px;color:#687990;font-size:8px;line-height:1.6}.pf-tip{border-color:rgba(251,191,36,.2);background:linear-gradient(145deg,rgba(251,191,36,.055),#0b1525)}.pf-tip strong{color:#f6d988;font-size:10px}.pf-tip p{margin:7px 0 0;color:#8b8066;font-size:8px;line-height:1.8}
        .orion-po-form .fi-sc-section{border:1px solid #22334d!important;border-radius:13px!important;background:#0f192b!important;box-shadow:none!important;overflow:hidden;margin-bottom:12px!important}.orion-po-form .fi-sc-section-header{background:#111c30!important;border-bottom:1px solid #1e2d45!important;padding:12px 14px!important}.orion-po-form .fi-sc-section-header-heading{color:#f3f6fb!important;font-size:11px!important;font-weight:950!important}.orion-po-form .fi-sc-section-header-description{color:#71829a!important;font-size:8px!important}.orion-po-form .fi-sc-section-content{padding:14px!important}.orion-po-form .fi-fo-field-wrp-label span{font-size:9px!important;font-weight:850!important;color:#9fafc3!important}.orion-po-form .fi-input-wrp{border-color:#2a3b56!important;background:#0b1525!important;border-radius:9px!important;box-shadow:none!important}.orion-po-form .fi-input-wrp:focus-within{border-color:var(--pf-purple)!important;box-shadow:0 0 0 1px rgba(139,92,246,.18)!important}.orion-po-form .fi-input,.orion-po-form .fi-select-input{font-size:10px!important;color:#eef3f8!important}.orion-po-form .fi-fo-repeater-item{border-color:#263853!important;background:#0c1627!important;border-radius:12px!important}
        @media(max-width:1100px){.pf-layout{grid-template-columns:1fr}.pf-side{position:static;grid-template-columns:repeat(2,1fr)}.pf-steps{grid-template-columns:repeat(2,1fr)}}@media(max-width:700px){.pf-steps,.pf-side{grid-template-columns:1fr}.pf-head{align-items:flex-start;flex-direction:column}}
    </style>

    <div class="orion-po-form">
        <div class="pf-steps">
            <div class="pf-step" style="--accent:var(--pf-blue)"><div class="pf-step-top"><span class="pf-step-title">بيانات الطلب</span><span class="pf-step-no">01</span></div><div class="pf-step-note">رقم الطلب والمورد وتاريخ الطلب والاستلام</div></div>
            <div class="pf-step" style="--accent:var(--pf-purple)"><div class="pf-step-top"><span class="pf-step-title">جهة الاستلام</span><span class="pf-step-no">02</span></div><div class="pf-step-note">حدد المخزن والفرع الذي سيستقبل التوريد</div></div>
            <div class="pf-step" style="--accent:var(--pf-green)"><div class="pf-step-top"><span class="pf-step-title">الأصناف والأسعار</span><span class="pf-step-no">03</span></div><div class="pf-step-note">الكميات المطلوبة وسعر الوحدة وإجمالي كل بند</div></div>
            <div class="pf-step" style="--accent:var(--pf-amber)"><div class="pf-step-top"><span class="pf-step-title">المراجعة والحفظ</span><span class="pf-step-no">04</span></div><div class="pf-step-note">راجع البيانات والتواريخ قبل إنشاء الطلب</div></div>
        </div>

        <div class="pf-layout">
            <div class="pf-shell">
                <div class="pf-head"><div><div class="pf-title">إنشاء طلب شراء جديد</div><div class="pf-sub">جهز الطلب بالكامل قبل إرساله للمورد</div></div><span class="pf-status">مسودة جديدة</span></div>
                <form wire:submit="create" class="pf-form">
                    {{ $this->form }}
                    <div class="pf-actions"><x-filament::actions :actions="$this->getFormActions()" /></div>
                </form>
            </div>
            <aside class="pf-side">
                <div class="pf-card"><div class="pf-kicker">PURCHASE CHECKLIST</div><div class="pf-card-title">قبل إنشاء الطلب</div><div class="pf-text">طلب الشراء الجيد يحدد المسؤولية والكمية والسعر وموعد الاستلام من البداية.</div><div class="pf-checks">
                    <div class="pf-check"><span class="pf-dot" style="--dot:var(--pf-blue)"></span><div><strong>المورد الصحيح</strong><span>تأكد من اختيار المورد المتفق معه على الأسعار والتوريد.</span></div></div>
                    <div class="pf-check"><span class="pf-dot" style="--dot:var(--pf-purple)"></span><div><strong>المخزن المستلم</strong><span>تحديد المخزن مهم عشان الاستلام ينعكس على المخزون الصح.</span></div></div>
                    <div class="pf-check"><span class="pf-dot" style="--dot:var(--pf-green)"></span><div><strong>الكميات والأسعار</strong><span>راجع الوحدة والكمية وسعر التكلفة لكل صنف.</span></div></div>
                    <div class="pf-check"><span class="pf-dot" style="--dot:var(--pf-amber)"></span><div><strong>موعد الاستلام</strong><span>إدخاله يخلي Orion يقدر يحدد الطلبات المتأخرة.</span></div></div>
                </div></div>
                <div class="pf-card pf-tip"><strong>Workflow</strong><p>ابدأ الطلب كمسودة، وبعد المراجعة انقله للحالة المناسبة. منطق الاعتماد والاستلام الفعلي لازم يفضل مربوط بالـModel أو Service المسؤول عن المخزون.</p></div>
            </aside>
        </div>
    </div>
</x-filament-panels::page>
